INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter booleschen Operatoren?', 2, '[{"text": "Logische Verknüpfungen", "correct": true, "because": "AND, OR, NOT"}, {"text": "Mathematische Operationen", "correct": false, "because": "Anderes Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit booleschen Operatoren?', 3, '[{"text": "Logische Bedingungen kombinieren", "correct": true, "because": "Entscheidungen treffen"}, {"text": "Speicherplatz sparen", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche booleschen Operatoren gibt es?', 5, '[{"text": "AND", "correct": true, "because": "Logisches UND"}, {"text": "OR", "correct": true, "because": "Logisches ODER"}, {"text": "NOT", "correct": true, "because": "Logische Negation"}, {"text": "ADD", "correct": false, "because": "Mathematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) AND verknüpft zwei Bedingungen. b) Es wird nur in SQL genutzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch andere Sprachen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei booleschen Operatoren?', 4, '[{"text": "Logische Bedeutung", "correct": false, "because": "Kern der Operatoren"}, {"text": "Reihenfolge", "correct": false, "because": "Priorität wichtig"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob AND zwei Bedingungen kombiniert?', 2, '[{"text": "Ja", "correct": true, "because": "Logisches UND"}, {"text": "Nein", "correct": false, "because": "Korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher boolesche Operator kehrt einen Wert um?', 3, '[{"text": "NOT", "correct": true, "because": "Negation"}, {"text": "AND", "correct": false, "because": "Verknüpfung"}, {"text": "OR", "correct": false, "because": "Verknüpfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Arbeit mit booleschen Operatoren?', 5, '[{"text": "Logische Ausdrücke", "correct": true, "because": "Bedingungen bilden"}, {"text": "Operatoren-Priorität", "correct": true, "because": "Reihenfolge beachten"}, {"text": "Textformatierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) OR ergibt true, wenn eine Bedingung wahr ist. b) Es wird nur für Zahlen genutzt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logische Werte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei booleschen Operatoren unwichtig?', 4, '[{"text": "Logische Verknüpfung", "correct": false, "because": "Hauptzweck"}, {"text": "Wahrheitswerte", "correct": false, "because": "Grundlage"}, {"text": "Schriftfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist NOT ein unärer Operator?', 2, '[{"text": "Ja", "correct": true, "because": "Ein Operand"}, {"text": "Nein", "correct": false, "because": "Korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten boolesche Operatoren?', 4, '[{"text": "Flexibilität bei Bedingungen", "correct": true, "because": "Kombinierbar"}, {"text": "Klarheit in Logik", "correct": true, "because": "Lesbar"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass boolesche Operatoren nur in SQL relevant sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Programmierung"}, {"text": "Ja", "correct": false, "because": "Universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei booleschen Operatoren?', 3, '[{"text": "Korrekte Logik", "correct": true, "because": "Funktionalität"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) AND ergibt true nur bei zwei wahren Bedingungen. b) OR ist immer false.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein falscher Einsatz boolescher Operatoren?', 5, '[{"text": "Falsche Ergebnisse", "correct": true, "because": "Logikfehler"}, {"text": "Programmfehler", "correct": true, "because": "Unerwartetes Verhalten"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei booleschen Operatoren?', 3, '[{"text": "Logische Bedingungen erstellen", "correct": true, "because": "Programmierung"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein boolescher Operator in SQL genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. WHERE"}, {"text": "Nein", "correct": false, "because": "Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis ergibt true AND false?', 4, '[{"text": "false", "correct": true, "because": "Nur beide true = true"}, {"text": "true", "correct": false, "because": "Logikfehler"}, {"text": "null", "correct": false, "because": "Kein SQL-NULL"}]');
